public static void setLanguage(Context context, String language) {
    if (!language.isEmpty() && !DEFAULT_LANGUAGE.equals(language) && !"zh-TW".equals(language) && !"en".equals(language)) {
        throw new IllegalArgumentException("Unsupported app language: " + language);
    }
    if (Build.VERSION.SDK_INT >= 33) {
        ((LocaleManager) context.getSystemService(LocaleManager.class)).setApplicationLocales(LocaleList.forLanguageTags(language));
    } else {
        preferences(context).edit().putString(LANGUAGE, language).apply();
        updateResources(context.getApplicationContext());
    }
}
